{
  "book_code": "4BAR",
  "verses": [
    {
      "chapter": 5,
      "text_ar": "وخرج من المدينة، وعندما بحث رأى معالم المدينة، وقال: «حقاً، هذه هي المدينة. لقد ضللت طريقي».",
      "verse": 11
    },
    {
      "chapter": 5,
      "text_ar": "ومرة أخرى عاد إلى المدينة وبحث، فلم يجد أحداً من شعبه، وقال: «مبارك هو الرب، لأن غشية عظيمة قد حلت بي!»",
      "verse": 12
    },
    {
      "chapter": 5,
      "text_ar": "ومرة أخرى خرج من المدينة، وبقي هناك حزيناً، لا يدري إلى أين يذهب.",
      "verse": 13
    },
    {
      "chapter": 5,
      "text_ar": "ووضع السلة، قائلاً: «سأجلس هنا حتى ينزع الرب هذه الغشية عني».",
      "verse": 14
    },
    {
      "chapter": 5,
      "text_ar": "وبينما كان جالساً، رأى شيخاً قادماً من الحقل، فقال له أبيمالك: «أقول لك ايها الشيخ، ما هذه المدينة؟»",
      "verse": 15
    }
  ]
}
